  <title>Symptoms & Topics — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#FFF8F3;--card:#FFF6F0;--ink:#2E2824;--accent:#7A4A2A;--muted:#6F5C55}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto;background:var(--bg);color:var(--ink)}
