    nav a{margin-left:14px;color:var(--muted);text-decoration:none}
    main{max-width:980px;margin:26px auto;padding:18px}
    .hero{background:var(--card);padding:18px;border-radius:12px}
    h1{margin:0 0 8px 0}
    .disclaimer{margin-top:12px;padding:12px;border-left:4px solid rgba(122,74,42,0.12);background:#FFF;border-radius:8px}
    .conditions{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-top:14px}
    .cond{background:#fff;padding:12px;border-radius:10px;border:1px solid rgba(46,40,36,0.04)}
    .try{margin-top:14px;display:flex;gap:10px;align-items:center}
    .btn{padding:10px 12px;border-radius:9px;border:0;background:var(--accent);color:#fff}
