    body::before{content:"";position:fixed;inset:0;pointer-events:none;opacity:0.04;background-image:url('data:image/svg+xml;utf8,<svg xmlns=%22http://www.w3.org/2000/svg%22 width=%22250%22 height=%22250%22><defs><pattern id=%22q%22 width=%2250%22 height=%2250%22 patternUnits=%22userSpaceOnUse%22><rect width=%2250%22 height=%2250%22 fill=%22%23FFF8F3%22/><g stroke=%22%237A4A2A%22 stroke-opacity=%220.06%22 stroke-width=%221%22><path d=%22M0 25 C12 10 38 40 50 25%22 fill=%22none%22/></g></pattern></defs><rect width=%22100%25%22 height=%22100%25%22 fill=%22url(%23q)%22/></svg>');mix-blend-mode:overlay}
