  <style>
    :root{--bg:#FFFCF9;--ink:#2B251F;--accent:#8F5A35;--muted:#7A6A61}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto;background:var(--bg);color:var(--ink)}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px;border-bottom:1px solid rgba(43,37,31,0.06)}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none}
    main{max-width:980px;margin:26px auto;padding:18px}
    .hero{background:linear-gradient(180deg,#FFFDF8,#FFF8F0);padding:18px;border-radius:12px}
    .process{display:flex;gap:14px;margin-top:16px}
    .step{flex:1;padding:12px;background:#fff;border-radius:10px}
    .tryBtn{margin-top:12px;padding:10px 12px;border-radius:9px;background:var(--accent);color:#fff;border:0}
    .miniInventory{margin-top:16px;padding:12px;background:#fff;border-radius:10px}
    footer{margin-top:26px;text-align:center;color:var(--muted)}
    /* unique geometric svg */
    body::after{content:"";position:fixed;right:0;top:0;width:320px;height:320px;background-image:url('data:image/svg+xml;utf8,<svg xmlns=%22http://www.w3.org/2000/svg%22 width=%22320%22 height=%22320%22><rect width=%22100%25%22 height=%22100%25%22 fill=%22%23FFFDF8%22/><g fill=%22%238F5A35%22 fill-opacity=%220.04%22><circle cx=%2260%22 cy=%2260%22 r=%2250%22/><rect x=%22160%22 y=%22140%22 width=%2290%22 height=%2290%22 transform=%22rotate(25 205 185)%22/></g></svg>');pointer-events:none}
    @media(max-width:760px){.process{flex-direction:column}}
  </style>
