<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center"><div style="width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,#F6E7D6,#FFF5ED);display:grid;place-items:center;color:var(--accent)">IM</div><div><strong>{{BUSINESS_NAME}}</strong></div></div>
    <nav>
      <a href="index.html">Home</a>
      <a href="approach.html">Method</a>
      <a href="services.html">Offerings</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>
  <main>
    <section class="hero">
      <h1>Method: structured curiosity and measurable moves</h1>
      <p class="small">We look for leverage — small changes with outsized influence on energy, mood and function — and build short, testable cycles around them.</p>
      <div style="margin-top:12px"><button class="tryBtn" id="openInventory">Try a short inventory</button></div>
    </section>

    <section class="process">
      <div class="step">
        <strong>Map</strong>
        <div class="small">Understand context: rhythms, demands, supports and constraints.</div>
      </div>
      <div class="step">
        <strong>Prioritize</strong>
        <div class="small">Choose one or two high-leverage targets for the cycle.</div>
      </div>
      <div class="step">
        <strong>Test & iterate</strong>
        <div class="small">Short cycles, measurement, and straightforward adjustments.</div>
      </div>
    </section>

    <section class="miniInventory">
      <strong>Mini inventory</strong>
      <div class="small">Select concerns to see the typical first-cycle focus and monitoring rhythm.</div>
      <div style="display:flex;gap:10px;margin-top:8px;flex-wrap:wrap">
        <button data-topic="Sleep" class="topicBtn">Sleep</button>
        <button data-topic="Stress" class="topicBtn">Stress</button>
        <button data-topic="Gut" class="topicBtn">Digestion</button>
        <button data-topic="Pain" class="topicBtn">Pain</button>
        <button data-topic="Energy" class="topicBtn">Energy</button>
      </div>
      <div id="miniResult" style="margin-top:12px"></div>
    </section>

